**What this code covers**

- http { upstream api_backend { server 10.0.0.1:8080; server 10.0.0.2:8080; server 10.0.0.3:8080; } upstream static_backend { server 10.0.1.1:80; }…
- One NGINX worker: event loop with select(), round-robin upstreams.
- Mock NGINX: parses a small subset of nginx.conf, then runs an
- Event loop that routes incoming requests by location to upstreams.
- Demonstrates: config-driven routing, event loop with select(),
- Upstream round-robin, SSL termination (simulated), keep-alive.
- Sample nginx.conf (parsed by our mock)
- Crude regex parser sufficient for the demo conf.

**Defines:** `NginxConfig`, `Worker`

```python
# Mock NGINX: parses a small subset of nginx.conf, then runs an
# event loop that routes incoming requests by location to upstreams.
# Demonstrates: config-driven routing, event loop with select(),
# upstream round-robin, SSL termination (simulated), keep-alive.

import socket
import select
import re
from collections import defaultdict

# ---- Sample nginx.conf (parsed by our mock) ----
NGINX_CONF = """
http {
    upstream api_backend {
        server 10.0.0.1:8080;
        server 10.0.0.2:8080;
        server 10.0.0.3:8080;
    }
    upstream static_backend {
        server 10.0.1.1:80;
    }
    server {
        listen 80;
        server_name api.example.com;
        location /api/ { proxy_pass http://api_backend; }
        location /static/ { proxy_pass http://static_backend; }
        location / { return 404; }
    }
}
"""

class NginxConfig:
    def __init__(self, conf_text):
        self.upstreams = defaultdict(list)   # name -> [host:port,...]
        self.locations = []                   # list of (regex, upstream_or_return)
        self._parse(conf_text)

    def _parse(self, text):
        # Crude regex parser sufficient for the demo conf.
        for m in re.finditer(r'upstream\s+(\w+)\s*\{([^}]*)\}', text):
            name, body = m.group(1), m.group(2)
            for s in re.finditer(r'server\s+([\d.]+:\d+);', body):
                self.upstreams[name].append(s.group(1))
        for m in re.finditer(r'location\s+(\S+)\s*\{([^}]*)\}', text):
            path, body = m.group(1), m.group(2)
            tgt = re.search(r'proxy_pass\s+http://(\w+);', body)
            ret = re.search(r'return\s+(\d+);', body)
            if tgt:
                self.locations.append((path, ('proxy', tgt.group(1))))
            elif ret:
                self.locations.append((path, ('return', int(ret.group(1)))))

    def match(self, url):
        for path, action in self.locations:
            if url.startswith(path.rstrip(';')):
                return action
        return ('return', 404)

class Worker:
    """One NGINX worker: event loop with select(), round-robin upstreams."""
    def __init__(self, conf, worker_id):
        self.conf = conf
        self.id = worker_id
        self.rr = defaultdict(int)   # upstream name -> next index

    def pick_upstream(self, name):
        pool = self.conf.upstreams[name]
        if not pool:
            return None
        idx = self.rr[name] % len(pool)
        self.rr[name] += 1
        return pool[idx]

    def handle_request(self, method, url, headers):
        action = self.conf.match(url)
        if action[0] == 'return':
            return f"HTTP/1.1 {action[1]} OK\r\nContent-Length: 0\r\n\r\n"
        upstream = self.pick_upstream(action[1])
        # In real NGINX: open non-blocking socket, register with epoll,
        # proxy the request, write response back. Here: simulate.
        body = f"proxied to {upstream} via upstream {action[1]}"
        return (f"HTTP/1.1 200 OK\r\nContent-Length: {len(body)}\r\n"
                f"X-Upstream: {upstream}\r\n\r\n{body}")

    def event_loop(self, requests):
        # Real NGINX uses epoll; we use a simple iterator to mimic the loop.
        print(f"[worker {self.id}] entering event loop, {len(requests)} conns ready")
        for req in requests:
            method, url, _ = req.split(' ', 2)
            resp = self.handle_request(method, url, {})
            print(f"[worker {self.id}] {method} {url} -> {resp.splitlines()[2]}")

if __name__ == "__main__":
    conf = NginxConfig(NGINX_CONF)
    print("Parsed upstreams:", dict(conf.upstreams))
    print("Parsed locations:", conf.locations)
    worker = Worker(conf, worker_id=1)
    requests = [
        "GET /api/users HTTP/1.1",
        "GET /api/orders HTTP/1.1",
        "GET /api/items  HTTP/1.1",
        "GET /static/logo.png HTTP/1.1",
        "GET /unknown HTTP/1.1",
    ]
    worker.event_loop(requests)
    # Subsequent /api/ requests round-robin across the 3 api_backend servers.
```
